-- Synthetic retail-bank schema. All data in these tables is SYNTHETIC (generated by scripts/seed.py).
-- Tables live in `bank`, not `public`, so Supabase's Data API (PostgREST) never exposes them.

create schema if not exists bank;
create schema if not exists app;        -- identity + helper functions, not readable by business roles
create schema if not exists analytics;  -- aggregate-only views (intern, auditor)
create schema if not exists extensions; -- Supabase already has it; created for vanilla Postgres in CI
create extension if not exists pgcrypto with schema extensions;

create table bank.branches (
    branch_id   smallint primary key,
    branch_code text not null unique,
    name        text not null,
    city        text not null,
    state       text not null,
    opened_on   date not null
);

create table bank.customers (
    customer_id        bigint primary key,
    branch_id          smallint not null references bank.branches,
    full_name          text not null,
    date_of_birth      date not null,
    national_id        text not null unique,            -- PII (synthetic)
    phone              text not null,                   -- PII (synthetic)
    email              text,
    city               text not null,
    segment            text not null check (segment in ('retail', 'priority', 'sme')),
    kyc_status         text not null check (kyc_status in ('verified', 'pending', 'expired')),
    created_at         timestamptz not null,
    national_id_masked text generated always as ('XXXXXXXX' || right(national_id, 4)) stored,
    phone_masked       text generated always as ('XXXXXX' || right(phone, 4)) stored
);
create index on bank.customers (branch_id);

create table bank.accounts (
    account_id            bigint primary key,
    customer_id           bigint not null references bank.customers,
    branch_id             smallint not null references bank.branches,
    account_number        text not null unique,          -- PII (synthetic)
    account_type          text not null check (account_type in ('savings', 'current', 'fixed_deposit')),
    status                text not null check (status in ('active', 'dormant', 'closed')),
    balance               numeric(14, 2) not null,
    currency              char(3) not null default 'INR',
    opened_on             date not null,
    closed_on             date,
    last_activity_at      timestamptz,
    account_number_masked text generated always as ('XXXXXXXXXX' || right(account_number, 4)) stored
);
create index on bank.accounts (branch_id);
create index on bank.accounts (customer_id);

create table bank.transactions (
    txn_id        bigint primary key,
    account_id    bigint not null references bank.accounts,
    branch_id     smallint not null references bank.branches,  -- denormalised from accounts for RLS + speed
    txn_at        timestamptz not null,
    txn_type      text not null check (txn_type in ('deposit', 'withdrawal', 'transfer_in', 'transfer_out', 'fee', 'interest')),
    channel       text not null check (channel in ('branch', 'atm', 'upi', 'netbanking', 'neft', 'imps', 'system')),
    amount        numeric(14, 2) not null check (amount > 0),
    balance_after numeric(14, 2) not null,
    description   text
);
create index on bank.transactions (branch_id, txn_at);
create index on bank.transactions (account_id, txn_at);

create table bank.loans (
    loan_id        bigint primary key,
    customer_id    bigint not null references bank.customers,
    branch_id      smallint not null references bank.branches,
    loan_type      text not null check (loan_type in ('home', 'personal', 'auto', 'business', 'gold')),
    principal      numeric(14, 2) not null check (principal > 0),
    interest_rate  numeric(5, 2) not null,
    disbursed_on   date not null,
    tenure_months  integer not null check (tenure_months > 0),
    outstanding    numeric(14, 2) not null check (outstanding >= 0),
    days_past_due  integer not null default 0 check (days_past_due >= 0),
    status         text not null check (status in ('current', 'overdue', 'npa', 'closed'))
);
create index on bank.loans (branch_id);

create table bank.employees (
    employee_id  integer primary key,
    branch_id    smallint references bank.branches,     -- null = head office
    full_name    text not null,
    job_title    text not null,
    department   text not null check (department in ('branch_ops', 'hr', 'audit', 'risk', 'it', 'executive', 'internship')),
    email        text not null unique,
    phone        text not null,                          -- PII (synthetic)
    hired_on     date not null,
    status       text not null check (status in ('active', 'left')),
    phone_masked text generated always as ('XXXXXX' || right(phone, 4)) stored
);
create index on bank.employees (branch_id);

create table bank.salaries (
    employee_id    integer not null references bank.employees,
    effective_from date not null,
    annual_ctc     numeric(12, 2) not null check (annual_ctc > 0),
    currency       char(3) not null default 'INR',
    primary key (employee_id, effective_from)
);

-- Which human is which business role. Source of truth for authorization:
-- the JWT only proves WHO the user is; this table decides WHAT they may see.
create table app.staff_users (
    auth_user_id uuid primary key,                       -- = Supabase auth.users.id = JWT `sub`
    employee_id  integer not null unique references bank.employees,
    app_role     text not null check (app_role in ('teller', 'branch_manager', 'hr', 'auditor', 'intern')),
    branch_id    smallint references bank.branches,
    active       boolean not null default true,
    check ((app_role in ('teller', 'branch_manager')) = (branch_id is not null))
);

-- HMAC key used to bind the end user's identity to a single DB transaction (see 0300 migration).
-- Inserted by scripts/setup_identity_key.py from an env secret, never in a migration.
create table app.identity_keys (
    key_id     text primary key,
    secret     bytea not null,
    active     boolean not null default true,
    created_at timestamptz not null default now()
);

create table app.dataset_meta (
    id           boolean primary key default true check (id),
    as_of        date not null,
    seed         integer not null,
    generated_at timestamptz not null default now(),
    note         text not null default 'SYNTHETIC data generated with Faker. Not real customers.'
);
